import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { CWSNService } from 'src/app/services/cwsn.service';
import { UserService } from 'src/app/services/emis/user.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
import { NetworkService } from 'src/app/services/network-service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { base64StringToBlob } from 'blob-util';
import { UploadService } from 'src/app/services/emis/upload.service';

@Component({
  selector: 'app-cwsn-school-list',
  templateUrl: './cwsn-school-list.page.html',
  styleUrls: ['./cwsn-school-list.page.scss'],
})
export class CwsnSchoolListPage implements OnInit {
  block_id: any;
  show:boolean=false;
  schoolList: any = [];
  items: any = [];
  itemHeight: number = 0;
  showtable: boolean;
  indexVal: any;
  allowGroup: boolean;
  schoolName: { label: string; value: string; type: string; }[];
  studentList: any;
  govtSchool: any;
  schoolType: any;
  GovSchlList: any=[];
  fullAidSchoolList: any=[];
  parAidSchlList: any=[];
  GovSchlList_duplicate: any;
  schoolSortlist: any;
  GovSchlSort: any=[];
  fullyAidedSort: any = [];
  parAidSchlsort: any=[];
  studentList_Duplicate: any=[];
  fullyAided_Duplicate: any=[];
  partially_Duplicate: any=[];
  userName: any;
  schoolTypeall: any;
  currNetWrkSts: any;
  spledutherachk: any;
  studentchkdata: any;
  studentpending: any[];
  finaldata: any[];
  dataobj: any[];
  studupdate: any[];
  BlkdId: any;
  filterSchoolList: any=[];
  schoolListShow: boolean = true;
  clsSecCounts: any;
  sectionList: any=[];
  sectionId: any;
  classId: any;
  schooltypeId: any;


  constructor( public navCtrl: NavController,private router: Router, private http: HttpClient, private route:ActivatedRoute,private alertService: AlertService,private userService: UserService,
    private userSessionService: UserSessionService,private cwsnService: CWSNService,private networkService: NetworkService,
    private ionicstorage: IonicStorageService,private uploadService: UploadService
    ) {
    this.items = [
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false },
      { expanded: false }
    ];
    this.indexVal = 1;
   }

  ngOnInit() {
    this.userName = this.userSessionService.emis_username();
    this.currNetWrkSts = this.networkService.getCurrentNetworkStatus();
    this.BlkdId = this.userSessionService.BlkdId();
    if(this.currNetWrkSts == 0){
      this.ionicstorage.getData('studentlistGet').then(
      async(data) => {
        if(data){
          this.studentchkdata = data;
          this.studentpending =[]
          for(let i=0;i<data.length;i++){
            if(data[i].Status == 2){
              this.studentpending.push(data[i]);
            }
          }
          if(this.studentpending){
            this.finaldata = []
            for(let i=0;i<this.studentpending.length;i++){
              if(this.studentpending[i].before_screening_photo){
                this.studentpending[i].before_screening_photo = await this.uploadPhoto(this.studentpending[i].before_screening_photo);
                this.studentpending[i].after_screening_photo = await this.uploadPhoto(this.studentpending[i].after_screening_photo);
                // this.studentpending[i].Status = 1
                this.finaldata.push(this.studentpending[i])
              }
            }
            if(this.finaldata){
              this.movelive()
            }
            
            if(this.userName){
              this.userCheck();
            }
          }
        }
        else{
          if(this.userName){
            this.userCheck();
          }
        }
      })
    }
    else{
      if(this.userName){
        this.userCheck();
      }
    }
 }

 ionViewDidEnter() {
  this.schoolListShow = true;
  this.clsSecCounts = 0;
  this.userName = this.userSessionService.emis_username();
  this.currNetWrkSts = this.networkService.getCurrentNetworkStatus();
  if(this.currNetWrkSts == 0){
    this.ionicstorage.getData('studentlistGet').then(
    async(data) => {
      if(data){
        this.studentchkdata = data;
        this.studentpending =[]
        for(let i=0;i<data.length;i++){
          if(data[i].Status == 2){
            this.studentpending.push(data[i]);
          }
        }
        if(this.studentpending){
          this.finaldata = []
          for(let i=0;i<this.studentpending.length;i++){
            if(this.studentpending[i].before_screening_photo){
              this.studentpending[i].before_screening_photo = await this.uploadPhoto(this.studentpending[i].before_screening_photo);
              this.studentpending[i].after_screening_photo = await this.uploadPhoto(this.studentpending[i].after_screening_photo);
              this.finaldata.push(this.studentpending[i])
            }
          }
          if(this.finaldata){
            this.movelive()
          }
          
          if(this.userName){
            this.userCheck();
          }
        }
      }
      // else{
      //   if(this.userName){
      //     this.userCheck();
      //   }
      // }
    })
  }
  else{
    if(this.userName){
      this.userCheck();
    }
  }
 }

 async uploadPhoto(base64string):Promise<void>{
  var bucketName = "renewalapplicationemis";
  let expiry: number = 300;
  const base = base64string.split('base64,');
  const blob = base64StringToBlob(base[1], 'image/jpg');
  if (blob.size <= 3145728) {
    if (this.currNetWrkSts == 0) {
      console.log('1')
    return  this.uploadService.getSignedUrl(bucketName, 'jpg', 'jpg', expiry).toPromise().then((result) => {
        if (result) {
          this.uploadService.uploadFile(result.url, blob).subscribe((res) => {
            console.log('3')
          });
          return result.key;
        }
      });
      console.log('4')
    }
  }
 }

 

 movelive(){
  this.dataobj = []
  this.finaldata
  for(let i=0;i<this.finaldata.length;i++){
    if(this.finaldata[i]){
      let obj = {
        IndxId: "",
        SchlId: this.finaldata[i].school_id,
        StdntId: this.finaldata[i].id,
        DisableType: this.finaldata[i].differently_abled,
        ScrnDate: this.finaldata[i].screening_date,
        BeforePhoto:this.finaldata[i].before_screening_photo,
        BeforeLong: this.finaldata[i].longitude_before_screening,
        BeforeLati: this.finaldata[i].latitude_before_screening,
        AfterPhoto:this.finaldata[i].after_screening_photo,
        AfterLong: this.finaldata[i].longitude_after_screening,
        AftereLati: this.finaldata[i].latitude_after_screening,
        StartTime: this.finaldata[i].start_time,
        EndTime: this.finaldata[i].end_time,
        Duration: this.finaldata[i].duration_intervention,
        Ques1: this.finaldata[i].question1,
        Ques2: this.finaldata[i].question2,
        Ques3: this.finaldata[i].question3,
      }
      this.dataobj.push(obj)
    }
  }

  if(this.dataobj){
    var data = {
      "records" : this.dataobj
    }
    this.cwsnService.trackingQues(data).subscribe(data => {
      if(data.dataStatus == true){
        this.alertService.success(data.message);
        this.ionicstorage.getData('studentlistGet').then(
          (data) => {
            if(data){
              this.studupdate = []
              for(let i=0;i<data.length;i++){
                data[i].Status = 1;
                this.studupdate.push(data[i])
              }
              if(this.studupdate){
                this.ionicstorage.insertData_Replace('studentlistGet',   this.studupdate);
              }
            }
          })
        this.router.navigate(["/tabs/cwsn/tracking-school-list"])
      }else{
        // this.alertService.error(data.message);
      }
    })
  }
 }

 userCheck(){
  this.spledutherachk = '';
  if(this.currNetWrkSts == 0){
    this.cwsnService.FindSplEdu_Therpst(this.userName).subscribe(data => {
      this.spledutherachk = data.result;
      this.ionicstorage.insertData_Replace('spleduTherapist',   data.result);

      if(this.spledutherachk == 2){
        this.homeBasedjson();
      }
      if(this.spledutherachk == 1){
        this.getBlockDetails();
      }
    })
  }
  else{
    this.ionicstorage.getData('spleduTherapist').then(
      (data) => {
        if(data){
          this.spledutherachk = data;

          if(this.spledutherachk == 2){
            this.homeBasedjson();
          }
          if(this.spledutherachk == 1){
            this.getBlockDetails();
          }
        }
       },
      (error) => console.error(error)
    );
  }
  
 }

  navigateSchoolList(i){
    if(this.indexVal == i) {
      this.indexVal = ''
    } else {
      this.indexVal = i
    }
    
  }

  stuList(i){
     let selectedList=i;
     let blockId = this.block_id;
     this.router.navigate(["/tabs/cwsn/tracking-stulist"], { queryParams: { 'studentdata':JSON.stringify(selectedList),
     'block_id': blockId }});
    console.log(this.schoolType,'this.schoolType')
  }

  homeBasedjson() {
    if(this.currNetWrkSts == 0){
      this.schoolTypeall = [];
      let schemeJson ='https://d1wpyxz35bzzz4.cloudfront.net/Homebased_ie_studends_list.json';
      this.http.get<any>(schemeJson).subscribe((data) => {
      this.schoolTypeall = data.Homebased_ie_studends_list;
      // this.schtype();
        if(this.schoolTypeall){
          this.schoolType = [];
          for(let i=0;i<this.schoolTypeall.length;i++){
            if(this.schoolTypeall[i].teacher_id == this.userName){
              this.schoolType.push(this.schoolTypeall[i])
            }
          }
          if(this.schoolType.length > 0){
            console.log(this.schoolType,"susus")
            this.ionicstorage.insertData_Replace('sclType',   this.schoolType)
            this.schtype()
          }
        }
      })
    }
    else{
      this.ionicstorage.getData('sclType').then(
        (dataa1) => {
          if(dataa1){
            this.schoolType = dataa1;
            console.log(this.schoolType,"susus1")
            this.schtype()
          }
         },
        (error) => console.error(error)
      );
    }
  }

  therapistjson(){
    if(this.currNetWrkSts == 0){
      this.schoolTypeall = [];
      let schemeJson ='https://d1wpyxz35bzzz4.cloudfront.net/therapist_home_based_stud_list_json.json  ';
      this.http.get<any>(schemeJson).subscribe((data) => {
      this.schoolTypeall = data.therapist_home_based_stud_list;
      // this.schtype();
        if(this.schoolTypeall){
          this.schoolType = [];
          for(let i=0;i<this.schoolTypeall.length;i++){
            if(this.schoolTypeall[i].block_id == this.block_id){
              this.schoolType.push(this.schoolTypeall[i])
            }
          }

          if(this.schoolType.length > 0){
            this.ionicstorage.insertData_Replace('sclType',   this.schoolType)
            this.schtype()
          }
        }
      })
    }
    else{
      this.ionicstorage.getData('sclType').then(
        (dataa1) => {
          if(dataa1){
            this.schoolType = dataa1;
            this.schtype()
          }
         },
        (error) => console.error(error)
      );
    }
  }

  schtype(){
    if (this.schoolType.length > 0) {
      this.GovSchlList=[];
      this.fullAidSchoolList=[];
      this.parAidSchlsort=[];
      this.fullyAidedSort=[];
      for (let i = 0; i < this.schoolType .length; i++) {
        if (this.schoolType [i].school_type_id == 1) { //  government
          this.GovSchlList.push(this.schoolType[i]);
          // console.log(this.GovSchlList,"this.GovSchlList");
          this.GovSchlSort = this.GovSchlList.map(l => { return { block_id:l.block_id,class_section:l.class_section,class_studying_id:l.class_studying_id,da_name:l.da_name,differently_abled:l.differently_abled,id:l.id,name:l.name,school_id: l.school_id,
            school_name: l.school_name, school_type_id:l.school_type_id,udise_code:l.udise_code,user_id:l.user_id

          }; 
          });
          this.GovSchlSort.sort((a, b) => {
            if (a.school_name < b.school_name)
              return -1;
            if (a.school_name > b.school_name)
              return 1;
            return 0;
          });
          this.studentList_Duplicate = this.GovSchlSort.filter((value, index, self) =>
          index === self.findIndex((t) => (
          t.school_name === value.school_name && t.school_name == value.school_name
          )))}
          if (this.schoolType[i].school_type_id == 2) { //fully-aided
            this.fullAidSchoolList.push(this.schoolType[i]);
            this.fullyAidedSort = this.fullAidSchoolList.map(l => { return {block_id:l.block_id,class_section:l.class_section,class_studying_id:l.class_studying_id,da_name:l.da_name,differently_abled:l.differently_abled,id:l.id,name:l.name,school_id: l.school_id,
            school_name: l.school_name, school_type_id:l.school_type_id,udise_code:l.udise_code,user_id:l.user_id

          }; 
          });
          this.fullyAidedSort.sort((a, b) => {
            if (a.school_name < b.school_name)
              return -1;
            if (a.school_name > b.school_name)
              return 1;
            return 0;
          });
          this.fullyAided_Duplicate = this.fullyAidedSort.filter((value, index, self) =>
          index === self.findIndex((t) => (
          t.school_name === value.school_name && t.school_name == value.school_name
          )))
          }
         if (this.schoolType[i].school_type_id == 4) { // partially-aided
           this.parAidSchlList.push(this.schoolType[i]);
           this.parAidSchlsort = this.parAidSchlList.map(l => { return {block_id:l.block_id,class_section:l.class_section,class_studying_id:l.class_studying_id,da_name:l.da_name,differently_abled:l.differently_abled,id:l.id,name:l.name,school_id: l.school_id,
            school_name: l.school_name, school_type_id:l.school_type_id,udise_code:l.udise_code,user_id:l.user_id

          }; });
           this.parAidSchlsort.sort((a, b) => {
            if (a.school_name < b.school_name)
              return -1;
            if (a.school_name > b.school_name)
              return 1;
            return 0;
          });
          this.partially_Duplicate = this.parAidSchlsort.filter((value, index, self) =>
          index === self.findIndex((t) => (
          t.school_name === value.school_name && t.school_name == value.school_name
          )))
          }
        }
        console.log(this.GovSchlSort,"GovSchlSort");
        console.log( this.fullyAidedSort," this.parAidSchlsort");
        console.log( this.parAidSchlsort," this.parAidSchlsort");
    }

  }



  getBlockDetails() {
    if(this.currNetWrkSts == 0){
      var getOoscUserDetails = []
      this.userService.getOoscUserDetails(this.userName).subscribe(res => {
        if (res.dataStatus == true) {
           getOoscUserDetails = res.result;
          if(getOoscUserDetails.length > 0) {
            this.block_id= getOoscUserDetails[0].TeacherBlockId;
            this.ionicstorage.insertData_Replace('blkId',   this.block_id)
            this.therapistjson();
          }
        } else {
          this.alertService.error("Something went wrong");
        }
      });
    }
    else{
      this.ionicstorage.getData('blkId').then(
        (dataa1) => {
          if(dataa1){
            this.block_id = dataa1;
            this.therapistjson();
          }
         },
        (error) => console.error(error)
      );
    }
  }

  goBack(){
    console.log(this.schoolListShow,"ooo")
    if(this.schoolListShow){
      this.router.navigate(['/tabs/cwsn/dashboard']);
    }
    else{
      if(this.clsSecCounts == 1){
        this.clsSecCounts = 0;
      }
      else{
        this.schoolListShow = true;
      }
      
    }
    
  }

  schoolSelected(item,val){
    this.filterSchoolList = [];
    if(val == 1){
      this.filterSchoolList = this.GovSchlList.filter((value) =>
        (
          value.school_id == item.school_id
        ));
    }
    if(val == 2){
      this.filterSchoolList = this.fullAidSchoolList.filter((value) =>
        (
          value.school_id == item.school_id
        ));
    }
    if(val == 3){
      this.filterSchoolList = this.parAidSchlList.filter((value) =>
        (
          value.school_id == item.school_id
        ));
    }

    if(this.filterSchoolList){
      this.filterSchoolList = this.filterSchoolList.filter((value, index, self) =>
        index === self.findIndex((t) => (
        t.class_studying_id === value.class_studying_id && t.class_section == value.class_section
        )));
        this.schoolListShow = false;
    }
    // this.router.navigate(['/tabs/cwsn-question-list'],{queryParams:{school_name:item.school_name,school_id:item.school_id}});
  }

  classSelected(val){
    this.classId = val.class_studying_id;
    this.clsSecCounts = 1;
    this.schooltypeId = val.school_type_id
    if(this.schooltypeId == 1 || this.schooltypeId == 2 || this.schooltypeId == 4){
      this.sectionList = [];
      for(let i=0;i< this.filterSchoolList.length;i++){
        if(this.filterSchoolList[i].class_studying_id == this.classId){
          this.sectionList.push(this.filterSchoolList[i])
        }
      }
    }
  }

  secSelected(data){
    console.log(data,'data',this.filterSchoolList)
    this.router.navigate(['/tabs/cwsn-question-list'],{queryParams:{school_name:data.school_name,school_id:data.school_id,class_id:this.classId,section_id:data.class_section,'school_list': JSON.stringify(this.filterSchoolList)}});
  }

}
